package lk.gov.health.govcare.draft;
import lk.gov.health.govcare.security.*;import org.springframework.web.bind.annotation.*;import java.util.*;import static lk.gov.health.govcare.draft.DraftDtos.*;
@RestController @RequestMapping("/api/workflow-drafts") public class DraftController {private final DraftService service;private final CurrentUser current;public DraftController(DraftService s,CurrentUser c){service=s;current=c;}@GetMapping public Map<String,Object> list(@RequestParam(defaultValue="")String workflowType){return Map.of("items",service.list(current.get(),workflowType));}@GetMapping("/{id}")public Map<String,Object> get(@PathVariable String id){return service.get(current.get(),id);}@PostMapping public Map<String,Object> save(@RequestBody SaveRequest q){return service.save(current.get(),q);}@PatchMapping("/{id}/archive")public Map<String,Object> archive(@PathVariable String id,@RequestBody(required=false)ActionRequest q){return service.archive(current.get(),id,q);}}
